import * as React from "react";
import { MpaIcon } from "../icon/MpaIcon";
import "./Checkbox.scss";


export interface CheckboxOption {
  id: string;
  name:string;
  label: string;
  value: string;
  disabled?: boolean;
}


export interface CheckboxProps {

  /**
  * Identifying value for the checkbox
  */
  id?: string;

  /**
  * Identifying name for the checkbox
  */
  name?: string;
  /**
   * Identify the checkbox value.
   */
  value?: string;
  
  /**
   * Determines whether this checkbox is checked.
   */
  checked?: boolean; 
  /**
   * Hex code that determines the background colour of the field when it is checked.
   */
  colour?: "primary" | "secondary" | "tertiary";
  /**
   * Custom onChange function that can be defined for the checkbox.
   */
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  /**
   * Text to be displayed below the input field in case of an error.
   */
  errorText?: string;
  /**
   * Boolean value that determines if the checkbox can be interacted with.
   */
  disabled?: boolean;
  /**
   * Custom classNames that can be provided for style extension / overrides.
   */
  className?: string;
  /**
   * The string to be displayed beside the check box.
  */
  label?: string;
}

export interface CheckboxProps {
  id?: string;
  checked?: boolean; 
  colour?: "primary" | "secondary" | "tertiary";
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  errorText?: string;
  disabled?: boolean;
  className?: string;
  label?: string;
}

export const Checkbox: React.FC<CheckboxProps> = ({
  id,
  name,
  value,
  checked,
  colour= "primary",
  onChange,
  errorText="",
  disabled,
  className="",
  label="Default Label",
  
}) => {
  const disabledClassName = ` ${disabled ? "disabled" : ""}`;

  return (
    <div className={`checkbox-wrapper ${className}`}>
        <label className={`checkbox-container ${disabledClassName} `}>
          <div className="checkbox-item">
          <input
            type="checkbox"
            id={id}
            name={name}
            // className={`checkbox-input ${colour} ${disabledClassName}`}
            className={`checkbox-input ${colour} `}
            disabled={disabled}
            style={{ accentColor: colour }}
            checked={checked}
            value={value}
            onChange={onChange}
          />
          <span className={`custom-checkbox ${colour} ${disabledClassName}`}></span>
          <div className={`hover-shadow ${colour}`}></div>
        </div>
        <div className={`check-label ${disabledClassName}`}>{label}</div>
      </label>

      {errorText?.trim() !== "" && (
        <div>
          <p className="error-text">
            <MpaIcon iconName="AlertCircle" colour="var(--mpa-red-80)" />
            <span className="error-text-padding">{errorText}</span>
          </p>
        </div>
      )}
    </div>
  );
};


export default Checkbox;


